cd /workspace/mytests && python3 - <<'EOF'
import random, sys
sys.path.insert(0,'/workspace/project'); sys.path.insert(0,'/workspace/mytests')
from modules import byte_program as bp
from cmp_nodes import build_node
from diff_parse import rand_channel
data = rand_channel(random.Random(5))
print(repr(data))
rnd = random.Random(5)
node = build_node(data, rnd)
def describe(n, d=0):
    print(' '*d + type(n).__name__, n.n, getattr(n,'lo',None))
    if type(n) is bp.Cat:
        for k in n.kids: describe(k, d+2)
    elif type(n) is bp.Rep:
        describe(n.kid, d+2)
    elif type(n) is bp.Cut:
        describe(n.kid, d+2)
describe(node)
print('full read ok:', bytes(bp.read_bytes(node,0,node.n))==data)
for i in range(0, len(data)):
    r = bytes(bp.read_bytes(node, i, i+1))
    if r != data[i:i+1]:
        print('read mismatch at', i, r, data[i:i+1]); break
for i in range(len(data)):
    got = bp.find_lf(node, i, min(node.n, i+8194))
    exp = data.find(b'\n', i, min(len(data), i+8194))
    if got != exp:
        print('find_lf mismatch at', i, got, exp); break
EOF
